def solve(G):
    G = np.array(G); H,W = G.shape
    lab,n = ndimage.label(G==3)
    boxes=[]
    for i in range(1,n+1):
        ys,xs = np.where(lab==i)
        boxes.append((ys.min(),ys.max(),xs.min(),xs.max()))
    out = G.copy()
    for r in range(H):
        for c in range(W):
            if G[r,c]==2 and any(r0<=r<=r1 and c0<=c<=c1 for r0,r1,c0,c1 in boxes):
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<H and 0<=cc<W and G[rr,cc]!=2:
                            out[rr,cc]=1
    return out
