def simulate(g, ringed_pred, overwrite_mode):
    g = g.copy(); H,W = g.shape
    lab,_ = ndimage.label(g==3)
    bbs = ndimage.find_objects(lab)
    twos = [(r,c) for r in range(H) for c in range(W) if g[r,c]==2]
    ringed = {(r,c) for r,c in twos if ringed_pred(r,c,bbs,g)}
    res = g.copy()
    for (r,c) in ringed:
        for rr in range(max(0,r-1),min(H,r+2)):
            for cc in range(max(0,c-1),min(W,c+2)):
                if (rr,cc)==(r,c): continue
                cur = res[rr,cc]
                if overwrite_mode=='all': res[rr,cc]=1
                elif overwrite_mode=='unringed2':
                    if cur!=2 or (rr,cc) not in ringed: res[rr,cc]=1
                elif overwrite_mode=='no2':
                    if cur!=2: res[rr,cc]=1
    return res, ringed

